const gv=$input.first().json;
const uc=$('Lookup user config').first().json;
const tg=uc.tg_notifs_chat_id||gv.tg_notifs_chat_id;
const email=uc.g_email_id||gv.g_email_id;
const owner=uc.backup_gh_owner||gv.backup_gh_owner;
return[{json:{...gv,tg_notifs_chat_id:tg,g_email_id:email,backup_gh_owner:owner}}];

function probe(name, extra) {
  try {
    const item = $(name).first();
    const j = (item && item.json) || {};
    const err = j.error || (item && item.error);
    if (err) {
      const msg = err.message || err.description || String(err);
      return extra({ ok: false, detail: String(msg).slice(0, 120) }, j);
    }
    return extra({ ok: true }, j);
  } catch (e) {
    return extra({ ok: false, detail: String(e.message || e).slice(0, 120) }, {});
  }
}
function line(label, r) {
  return label + ': ' + (r.ok ? 'working' : ('not working' + (r.detail ? ' (' + r.detail + ')' : '')));
}
const gh = probe('Check if repo is starred', (base, j) => {
  const c = Number(j.statusCode);
  if (c === 204) return { ok: true, starred: true };
  if (c === 404) return { ok: true, starred: false };
  if (!base.ok) return base;
  return { ok: false, detail: 'HTTP ' + c };
});
const gmail = probe('Check Gmail', (base) => base);
const tg = probe('Check Telegram', (base) => base);
const sb = probe('Check Supabase', (base) => base);
const jina = probe('Check Jina', (base) => base);
const n8nApi = probe('Check n8n', (base) => base);
let starLine = 'You have not starred';
if (gh.ok && gh.starred) starLine = 'You have starred';
const checks = [['Gmail', gmail], ['GitHub', gh], ['Telegram', tg], ['Supabase', sb], ['Jina', jina], ['n8n', n8nApi]];
const credReport = checks.map(([label, r]) => line(label, r)).join('\n');
const failed = checks.filter(([, r]) => !r.ok).map(([label]) => label);
const allCredsOk = failed.length === 0;
const cfg = $('Attach repo config').first().json;
const copyLine = 'Copied user_config into global_variables.';
const importLine = allCredsOk ? 'GitHub import will run next.' : ('GitHub import skipped. Failed checks: ' + failed.join(', ') + '.');
return [{ json: { starLine, credReport, allCredsOk, text: copyLine + '\n' + importLine + '\n\n' + starLine + '\n\n' + credReport, tg_notifs_chat_id: cfg.tg_notifs_chat_id } }];

const s=$getWorkflowStaticData('global');
s.importCounts={created:0,skipped:0,failed:0,listed:0};
return $input.all();

