const listed=$('List GitHub workflow files').all().map(i=>i.json).filter(f=>f&&f.type==='file'&&/\.json$/i.test(String(f.name||''))&&String(f.name).includes('__'));
const existing=$('Check n8n').all().map(i=>i.json);
const existingNames=existing.map(w=>w.name);
const existingIds=existing.map(w=>String(w.id));
const s=$getWorkflowStaticData('global');
s.importCounts=s.importCounts||{created:0,skipped:0,failed:0,listed:0};
s.importCounts.listed=listed.length;
const repo_owner='hellovamsi';
const repo_name='sorted_signals';
const repo_path='workflows/';
const repo_branch='main';
if(!listed.length){return[{json:{hasFiles:false,repo_owner,repo_name}}];}
return listed.map(f=>({json:{hasFiles:true,name:f.name,path:f.path,download_url:f.download_url,sha:f.sha,size:f.size,repo_owner,repo_name,repo_path,repo_branch,existingNames,existingIds}}));

const item=$input.first().json;
const orig=$('When called for one file').first().json;
let raw;
if(item.content){raw=JSON.parse(Buffer.from(item.content,'base64').toString('utf8'));}
else if(typeof item.data==='string'&&item.data.trim().startsWith('{')){raw=JSON.parse(item.data);}
else if(item.nodes&&item.name){raw=item;}
else{throw new Error('Could not parse workflow JSON from GitHub file');}
const names=new Set(orig.existingNames||[]);
const ids=new Set((orig.existingIds||[]).map(String));
const exportId=raw.id!=null?String(raw.id):'';
const name=String(raw.name||'');
let action='create';
let skipReason='';
if(name==='master : setup'||name==='import : github'){action='skip';skipReason='self';}
else if((exportId&&ids.has(exportId))||names.has(name)){action='skip';skipReason='already_on_instance';}
const settings=raw.settings&&typeof raw.settings==='object'?{...raw.settings}:{};
const workflowObject={name,nodes:raw.nodes||[],connections:raw.connections||{},settings};
return[{json:{action,skipReason,name,exportId,fileName:orig.name,workflowObject:JSON.stringify(workflowObject)}}];

